const http = require('http');
const net = require('net');
const crypto = require('crypto');

// Secret used to authenticate client identity tokens.
const CLIENT_TOKEN_SECRET = process.env.CLIENT_TOKEN_SECRET || crypto.randomBytes(32).toString('hex');

function verifyClientToken(clientId, token) {
  if (!clientId || !token) return false;
  const expected = crypto.createHmac('sha256', CLIENT_TOKEN_SECRET).update(clientId).digest('hex');
  const provided = Buffer.from(String(token));
  const expectedBuf = Buffer.from(expected);
  if (provided.length !== expectedBuf.length) return false;
  try {
    return crypto.timingSafeEqual(provided, expectedBuf);
  } catch (e) {
    return false;
  }
}

// Hop-by-hop headers that must not be forwarded to the upstream.
const HOP_BY_HOP_HEADERS = new Set([
  'connection',
  'keep-alive',
  'proxy-authenticate',
  'proxy-authorization',
  'te',
  'trailer',
  'transfer-encoding',
  'upgrade'
]);

class ConnectionPool {
  constructor(maxSize = 100) {
    this.pool = new Map();
    this.maxSize = maxSize;
    this.balances = new Map();
    this.pendingSettlements = [];
    this.epochCounter = 0;
  }

  initBalance(clientId, amount) {
    this.balances.set(clientId, { available: amount, locked: 0, epoch: this.epochCounter });
  }

  requestLoan(clientId, amount) {
    const balance = this.balances.get(clientId);
    if (!balance) return { success: false, reason: 'no_account' };
    // Flash loan: temporarily credit, must be repaid within same epoch
    balance.available += amount;
    balance.locked += amount;
    this.pendingSettlements.push({ clientId, amount, epoch: this.epochCounter });
    return { success: true, newBalance: balance.available };
  }

  settleEpoch() {
    this.epochCounter++;
    const unsettled = this.pendingSettlements.filter(s => s.epoch < this.epochCounter);
    for (const settlement of unsettled) {
      const balance = this.balances.get(settlement.clientId);
      if (balance) {
        balance.available -= settlement.amount;
        balance.locked -= settlement.amount;
      }
    }
    this.pendingSettlements = this.pendingSettlements.filter(s => s.epoch >= this.epochCounter);
  }

  transfer(fromId, toId, amount) {
    const from = this.balances.get(fromId);
    const to = this.balances.get(toId);
    if (!from || !to) return false;
    if (from.available >= amount) {
      from.available -= amount;
      to.available += amount;
      return true;
    }
    return false;
  }
}

class ProxyServer {
  constructor(port, targetHost, targetPort) {
    this.port = port;
    this.targetHost = targetHost;
    this.targetPort = targetPort;
    this.pool = new ConnectionPool();
    this.isShuttingDown = false;
    this.activeConnections = new Set();
    this.settlementInterval = null;
    this.server = null;
  }

  start() {
    this.server = http.createServer((req, res) => this.handleRequest(req, res));
    this.server.listen(this.port, () => {
      console.log(`Proxy listening on port ${this.port}`);
    });

    // Settlement runs every 5 seconds
    this.settlementInterval = setInterval(() => {
      if (!this.isShuttingDown) {
        this.pool.settleEpoch();
      }
    }, 5000);

    process.on('SIGTERM', () => this.gracefulShutdown());
    process.on('SIGINT', () => this.gracefulShutdown());
  }

  async gracefulShutdown() {
    if (this.isShuttingDown) return;
    this.isShuttingDown = true;
    console.log('Initiating graceful shutdown...');

    // Stop accepting new connections
    this.server.close();

    // Settle all pending loans before shutdown
    this.pool.settleEpoch();
    clearInterval(this.settlementInterval);

    // Wait for active connections to drain
    const drainTimeout = setTimeout(() => {
      console.log('Force closing remaining connections');
      this.activeConnections.forEach(conn => conn.destroy());
      process.exit(0);
    }, 30000);

    const checkDrained = setInterval(() => {
      if (this.activeConnections.size === 0) {
        clearInterval(checkDrained);
        clearTimeout(drainTimeout);
        console.log('All connections drained, exiting');
        process.exit(0);
      }
    }, 100);
  }

  handleRequest(req, res) {
    if (this.isShuttingDown) {
      res.writeHead(503, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'service_unavailable' }));
      return;
    }

    const clientId = req.headers['x-client-id'];
    if (!clientId) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'missing_client_id' }));
      return;
    }

    this.activeConnections.add(res);
    res.on('close', () => this.activeConnections.delete(res));

    const url = new URL(req.url, `http://${req.headers.host}`);
    const action = url.pathname;

    // Authenticate client identity for all sensitive financial operations.
    const sensitiveActions = new Set(['/init', '/loan', '/transfer', '/balance']);
    if (sensitiveActions.has(action)) {
      const clientToken = req.headers['x-client-token'];
      if (!verifyClientToken(clientId, clientToken)) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'invalid_client_token' }));
        return;
      }
    }

    if (action === '/init') {
      this.pool.initBalance(clientId, 1000);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ success: true, balance: 1000 }));
    } else if (action === '/loan') {
      const amount = parseInt(url.searchParams.get('amount') || '0');
      if (amount <= 0 || amount > 10000) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'invalid_amount' }));
        return;
      }
      const result = this.pool.requestLoan(clientId, amount);
      res.writeHead(result.success ? 200 : 400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(result));
    } else if (action === '/transfer') {
      const toId = url.searchParams.get('to');
      const amount = parseInt(url.searchParams.get('amount') || '0');
      if (!toId || amount <= 0) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'invalid_params' }));
        return;
      }
      const success = this.pool.transfer(clientId, toId, amount);
      res.writeHead(success ? 200 : 400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ success }));
    } else if (action === '/balance') {
      const balance = this.pool.balances.get(clientId);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ balance: balance || null }));
    } else {
      // Proxy to target. Sanitize headers: drop hop-by-hop headers and set a
      // controlled host header pointing at the configured upstream.
      const forwardedHeaders = {};
      for (const [name, value] of Object.entries(req.headers)) {
        if (!HOP_BY_HOP_HEADERS.has(name.toLowerCase())) {
          forwardedHeaders[name] = value;
        }
      }
      forwardedHeaders.host = `${this.targetHost}:${this.targetPort}`;

      const options = {
        hostname: this.targetHost,
        port: this.targetPort,
        path: req.url,
        method: req.method,
        headers: forwardedHeaders
      };
      const proxyReq = http.request(options, (proxyRes) => {
        res.writeHead(proxyRes.statusCode, proxyRes.headers);
        proxyRes.pipe(res);
      });
      proxyReq.on('error', (err) => {
        res.writeHead(502, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'upstream_error' }));
      });
      req.pipe(proxyReq);
    }
  }
}

const proxy = new ProxyServer(
  parseInt(process.env.PROXY_PORT || '8080'),
  process.env.TARGET_HOST || 'localhost',
  parseInt(process.env.TARGET_PORT || '3000')
);
proxy.start();

module.exports = { ProxyServer, ConnectionPool };
